settings.custom_css:
selector { flex-grow: 1; }
@media (max-width: 1200px) {
  selector { flex-grow: 0; }
}

@media (min-width: 1201px) {
  selector .e-n-menu-title { position: relative; }
  selector .e-n-menu-title::after {
    content: ""; position: absolute; left: 12px; right: 12px; bottom: 4px;
    height: 2px; background: #231B2B;
    transform: scaleX(0); transform-origin: left; transition: transform .15s;
  }
  selector .e-n-menu-title:hover::after,
  selector .e-n-menu-title.e-current::after { transform: scaleX(1); }
}
/* Desplegable: debajo del header (80 px), a todo el ancho y sin marco; el puente invisible evita que se cierre al bajar el mouse */
@media (min-width: 1201px) {
  selector .e-n-menu-content { top: calc(100% + 21px) !important; }
  selector .e-n-menu-content::before { content: ""; position: absolute; left: 0; right: 0; top: -21px; height: 21px; }
  selector .e-n-menu-content > .e-con { --padding-top: 0px; --padding-right: 0px; --padding-bottom: 0px; --padding-left: 0px; padding: 0 !important; background: transparent !important; border-top: 1px solid rgba(35,27,43,.16); }
  selector .e-n-menu-content > .e-con > .e-con { box-shadow: none !important; }
}
/* fin desplegable */

/* Menú móvil: abre debajo del header, con una línea arriba y sombra para separarlo del contenido */
@media (max-width: 1200px) {
  selector .e-n-menu-wrapper { border-top: 1px solid rgba(35,27,43,.16); box-shadow: 0 16px 32px rgba(35,27,43,.14); max-height: calc(100vh - 80px); overflow-y: auto; }
}
/* fin menú móvil */

selector { flex-shrink: 0; }
selector .elementor-button { white-space: nowrap; }
@media (max-width: 767px) {
  selector .elementor-button-icon { display: none; }
}
